INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time) VALUES (1, '全国两会召开', '2025年全国两会在北京隆重召开，代表们齐聚一堂，共商国是。本次会议将持续7天，聚焦经济发展、民生保障等重大议题。', '国内新闻,最新动态', '本次会议聚焦民生热点，提出多项重要议案。', 1, 'https://picsum.photos/id/10/360/180', '动态,国内', 0, '2025-11-21 09:00:14', '2025-11-24 05:46:28');
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time) VALUES (2, '本地交通新规实施', '本市新交通规则正式生效，市民需注意出行变化。新规包括早晚高峰限行时段调整、停车费标准调整等内容。', '本地新闻', '新规包括限行时段调整、停车费调整等。', 1, 'https://picsum.photos/id/110/360/180', '动态', 0, '2025-11-21 09:00:14', '2025-11-24 06:40:30');
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time) VALUES (3, '国际油价波动', '受地缘政治影响，国际原油价格出现大幅波动。布伦特原油期货价格上涨3.5%，WTI原油期货上涨4.2%。', '国际信息', '专家分析称未来油价走势仍存不确定性。', 1, 'https://picsum.photos/id/30/360/180', '国际', 0, '2025-11-21 09:00:14', '2025-11-24 05:46:28');
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time) VALUES (4, '新游戏《星际征途》上线', '备受期待的太空探索游戏今日全球发布。游戏采用虚幻5引擎打造，支持光线追踪技术，画面震撼。', '游戏新闻', '游戏采用虚幻5引擎，画面震撼。', 1, 'https://picsum.photos/id/40/360/180', '游戏', 0, '2025-11-21 09:00:14', '2025-11-24 05:46:28');
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time) VALUES (5, '军事演习圆满结束', '我国东部海域联合军事演习圆满结束。此次演习展示了我军现代化装备水平，检验了联合作战能力。', '国内新闻,最新动态', '此次演习展示了我军现代化装备水平。', 1, 'https://picsum.photos/id/50/360/180', '动态,国内,军事', 0, '2025-11-21 09:00:14', '2025-11-24 05:46:28');
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time) VALUES (6, '本地楼市新政发布', '本市住建局发布楼市调控新政，涉及限购、限贷等多项内容。新政将于下月起正式实施，旨在稳定房价。', '本地新闻', '新政涉及限购、限贷等多项措施。', 0, 'https://picsum.photos/id/60/360/180', '动态', 0, '2025-11-21 09:00:14', '2025-11-24 08:05:06');
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time) VALUES (7, '联合国气候大会召开', '1', '国际信息', '各国承诺加大减排力度，应对气候变化。', 1, 'https://picsum.photos/id/70/360/180', '动态', 0, '2025-11-21 09:00:14', '2025-11-25 05:40:12');
INSERT INTO userdb.news (id, news_name, news_content, news_category, news_description, has_image, image_url, news_tags, deleted, create_time, update_time) VALUES (8, '热门手游迎来周年庆', '知名手游《王者荣耀》迎来7周年庆典，推出限定皮肤和丰富活动。玩家参与度创历史新高。', '游戏新闻,最新动态', '周年庆活动丰富，玩家热情高涨。', 1, 'https://picsum.photos/id/80/360/180', '游戏,动态', 0, '2025-11-21 09:00:14', '2025-11-24 05:46:28');
